(() => {
  // (pictures only) cut the old 'oldsand' paint cells off the circuit edge band (19. 10.); window.__PAINTCUT(0/1)
  if (window.__PAINTCUT) window.__PAINTCUT(0);
  const D = {"x0": -219.0, "z0": -262.0, "S": 0.25, "nx": 1624, "nz": 1716, "m": ""}, bin = atob(D.m), M = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) M[i] = bin.charCodeAt(i);
  const smp = (x, z) => { const fx = (x - D.x0) / D.S - 0.5, fz = (z - D.z0) / D.S - 0.5, ix = Math.floor(fx), iz = Math.floor(fz); if (ix < 0 || iz < 0 || ix >= D.nx - 1 || iz >= D.nz - 1) return 0; const tx = fx - ix, tz = fz - iz, k = iz * D.nx + ix;
    return ((M[k] * (1 - tx) + M[k + 1] * tx) * (1 - tz) + (M[k + D.nx] * (1 - tx) + M[k + D.nx + 1] * tx) * tz) / 255; };
  const root = window.__PAINTROOT && window.__PAINTROOT['oldsand']; if (!root) return 'PAINTCUT no root';
  const V = new THREE.Vector3(); let nm = 0, nv = 0, cut = 0; const keep = [];
  root.updateMatrixWorld(true);
  root.traverse(o => { if (!o.isMesh || !o.geometry.attributes.color || o.geometry.attributes.color.itemSize !== 4) return; nm++;
    const P = o.geometry.attributes.position, C = o.geometry.attributes.color, orig = new Float32Array(C.count), cutv = new Float32Array(C.count);
    for (let i = 0; i < P.count; i++) { V.fromBufferAttribute(P, i).applyMatrix4(o.matrixWorld); const m = smp(V.x, V.z), a = C.getW(i); orig[i] = a; cutv[i] = a * (1 - m); if (m > 0.02) { nv++; if (m > 0.5) cut++; } }
    keep.push([C, orig, cutv]); });
  window.__PAINTCUT = (on) => { for (const [C, orig, cutv] of keep) { for (let i = 0; i < C.count; i++) C.setW(i, on ? cutv[i] : orig[i]); C.needsUpdate = true; } };
  window.__PAINTCUT(1);
  return 'PAINTCUT meshes ' + nm + ' touched ' + nv + ' cut ' + cut; })()